/**
 * Finds the first cycle a depth-first search discovers when it starts from
 * each task in ascending name order and walks each task's dependencies in
 * ascending name order. Returns the cycle as an array of names running from
 * the re-entered task, through the search stack, back to that task, or
 * `null` when the graph is acyclic.
 */
function findCycle(tasks, deps) {
  const state = new Map() // name -> 'visiting' | 'done'
  const stack = []

  function visit(name) {
    state.set(name, 'visiting')
    stack.push(name)
    for (const dep of deps.get(name)) {
      const depState = state.get(dep)
      if (depState === 'visiting') {
        const start = stack.indexOf(dep)
        return [...stack.slice(start), dep]
      }
      if (depState !== 'done') {
        const cycle = visit(dep)
        if (cycle) return cycle
      }
    }
    state.set(name, 'done')
    stack.pop()
    return null
  }

  for (const name of [...tasks.keys()].sort()) {
    if (!state.has(name)) {
      const cycle = visit(name)
      if (cycle) return cycle
    }
  }
  return null
}

/**
 * Validates the graph is acyclic, throwing a `CliError` (exit 3) naming the
 * first cycle found otherwise.
 */
export function checkAcyclic(tasks, deps) {
  const cycle = findCycle(tasks, deps)
  if (cycle) {
    throw new CliError(`error: cycle: ${cycle.join(' -> ')}`, 3)
  }
}

/**
 * Computes, for every task, its wave (longest dependency chain in edges),
 * start (greatest dependency finish, or 0), and finish (start + cost).
 */
export function computeSchedule(tasks, deps) {
  const depth = new Map()
  const finish = new Map()

  function depthOf(name) {
    if (depth.has(name)) return depth.get(name)
    let d = 0
    for (const dep of deps.get(name)) {
      d = Math.max(d, depthOf(dep) + 1)
    }
    depth.set(name, d)
    return d
  }

  function finishOf(name) {
    if (finish.has(name)) return finish.get(name)
    let start = 0
    for (const dep of deps.get(name)) {
      start = Math.max(start, finishOf(dep))
    }
    const f = start + tasks.get(name).cost
    finish.set(name, f)
    return f
  }

  const result = new Map()
  let total = 0
  for (const name of tasks.keys()) {
    const d = depthOf(name)
    const f = finishOf(name)
    let start = 0
    for (const dep of deps.get(name)) start = Math.max(start, finishOf(dep))
    result.set(name, { start, finish: f, depth: d })
    total = Math.max(total, f)
  }
  return { perTask: result, total }
}

/**
 * Computes, for every task, the cost of the longest chain that begins at
 * it and runs forward through dependents to a task nothing depends on.
 */
function computePriorities(tasks, deps) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, depList] of deps) {
    for (const dep of depList) dependents.get(dep).push(name)
  }

  const priority = new Map()
  function priorityOf(name) {
    if (priority.has(name)) return priority.get(name)
    let downstream = 0
    for (const child of dependents.get(name)) {
      downstream = Math.max(downstream, priorityOf(child))
    }
    const p = tasks.get(name).cost + downstream
    priority.set(name, p)
    return p
  }

  for (const name of tasks.keys()) priorityOf(name)
  return priority
