/**
 * Simulates the build graph on a fixed number of workers, greedily
 * starting the highest-priority ready task on the lowest-index free
 * worker whenever both exist at the current instant.
 */
export function pack(tasks, deps, workerCount) {
  const priority = computePriorities(tasks, deps)
  const names = [...tasks.keys()]
  const started = new Set()
  const finishTime = new Map()

  const workers = Array.from({ length: workerCount }, () => ({ busyUntil: 0, runs: [] }))
  let time = 0
  let remaining = names.length

  const isReady = (name) => {
    for (const dep of deps.get(name)) {
      const f = finishTime.get(dep)
      if (f === undefined || f > time) return false
    }
    return true
  }

  while (remaining > 0) {
    let progressed = true
    while (progressed) {
      progressed = false
      const freeIndex = workers.findIndex((w) => w.busyUntil <= time)
      if (freeIndex === -1) break

      let best = null
      for (const name of names) {
        if (started.has(name) || !isReady(name)) continue
        if (
          best === null ||
          priority.get(name) > priority.get(best) ||
          (priority.get(name) === priority.get(best) && name < best)
        ) {
          best = name
        }
      }
      if (best === null) break

      const cost = tasks.get(best).cost
      const finish = time + cost
      started.add(best)
      finishTime.set(best, finish)
      workers[freeIndex].busyUntil = finish
      workers[freeIndex].runs.push({ name: best, start: time, finish })
