    let next = Infinity
    for (const w of workers) {
      if (w.busyUntil > time) next = Math.min(next, w.busyUntil)
    }
    time = next
  }

  const makespan = workers.reduce((m, w) => Math.max(m, w.busyUntil), 0)
  return { workers, makespan }
}
