import { CliError } from './errors.js'
import { parseInput } from './parse.js'
import { checkAcyclic, computeSchedule, pack } from './graph.js'

const USAGE = 'error: usage: cli.js waves|explain|pack <workers>'
const WORKERS_RE = /^(?:[1-9][0-9]*)$/

function readStdin() {
  return new Promise((resolve, reject) => {
    const chunks = []
    process.stdin.on('data', (chunk) => chunks.push(chunk))
    process.stdin.on('end', () => resolve(Buffer.concat(chunks).toString('utf8')))
    process.stdin.on('error', reject)
  })
}

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!WORKERS_RE.test(argv[1])) {
      throw new CliError('error: workers must be a positive integer', 2)
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw new CliError(USAGE, 2)
}

function runWaves(tasks, deps) {
  const { perTask, total } = computeSchedule(tasks, deps)
  const waves = []
  for (const [name, info] of perTask) {
    if (!waves[info.depth]) waves[info.depth] = []
    waves[info.depth].push(name)
  }
  const lines = []
  for (let i = 0; i < waves.length; i++) {
    lines.push(`wave ${i}: ${waves[i].sort().join(' ')}`)
  }
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function runExplain(tasks, deps) {
  const { perTask, total } = computeSchedule(tasks, deps)
  const lines = []
  for (const name of [...tasks.keys()].sort()) {
    const { start, finish, depth } = perTask.get(name)
    lines.push(`${name} start=${start} finish=${finish} depth=${depth}`)
  }
  lines.push(`total ${total}`)
  return lines.join('\n') + '\n'
}

function runPack(tasks, deps, workerCount) {
  const { workers, makespan } = pack(tasks, deps, workerCount)
  const lines = workers.map((w, i) => {
    const runs = w.runs.map((r) => ` ${r.name}@${r.start}-${r.finish}`).join('')
    return `worker ${i}:${runs}`
  })
  lines.push(`makespan ${makespan}`)
  return lines.join('\n') + '\n'
}

async function main() {
  const argv = process.argv.slice(2)
  const args = parseArgs(argv)

  const input = await readStdin()
  const { tasks, deps } = parseInput(input)
  checkAcyclic(tasks, deps)

  if (args.mode === 'waves') {
    process.stdout.write(runWaves(tasks, deps))
  } else if (args.mode === 'explain') {
    process.stdout.write(runExplain(tasks, deps))
  } else {
    process.stdout.write(runPack(tasks, deps, args.workers))
  }
}

main().catch((err) => {
  if (err instanceof CliError) {
    process.stderr.write(err.message + '\n')
    process.exit(err.exitCode)
  }
  throw err
})
